/* @autogenerated */
package net.civeira.phylax.common.infrastructure.migration;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.mockStatic;
import static org.mockito.Mockito.when;

import java.sql.Connection;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.stream.Stream;

import javax.sql.DataSource;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.mockito.MockedStatic;

import io.agroal.api.AgroalDataSource;
import io.agroal.api.configuration.AgroalDataSourceConfiguration;
import jakarta.enterprise.inject.Instance;
import net.civeira.phylax.common.infrastructure.migration.MigrationsManager.JdbcConfig;
import net.civeira.phylax.common.infrastructure.migration.MigrationsManager.MigrationsConfig;
import net.civeira.phylax.common.infrastructure.migration.MigrationsUnitTest.FakeDb;
import net.civeira.phylax.common.infrastructure.sql.UncheckedSqlException;

@DisplayName("MigrationsManager")
class MigrationsManagerUnitTest {

  private static MigrationsConfig config(Optional<JdbcConfig> jdbc) {
    MigrationsConfig config = mock(MigrationsConfig.class);
    when(config.jdbc()).thenReturn(jdbc);
    when(config.dbKind()).thenReturn(Optional.of("mariadb"));
    when(config.username()).thenReturn(Optional.of("user"));
    when(config.password()).thenReturn(Optional.of("secret"));
    when(config.location()).thenReturn(Optional.of("migrations-unit/changelog.txt"));
    when(config.group()).thenReturn(Optional.empty());
    return config;
  }

  @SuppressWarnings("unchecked")
  private static Instance<MigrationSeed> seeds(MigrationSeed... seeds) {
    Instance<MigrationSeed> instance = mock(Instance.class);
    when(instance.stream()).thenAnswer(_ -> Stream.of(seeds));
    return instance;
  }

  private static MigrationSeed seed(List<String> ran) {
    return new MigrationSeed() {
      @Override
      public String id() {
        return "seed";
      }

      @Override
      public void run() {
        ran.add("seed");
      }
    };
  }

  @Test
  @DisplayName("Should migrate and seed the application datasource")
  void shouldUseApplicationDatasource() throws SQLException {
    FakeDb db = new FakeDb();
    Connection connection = db.connection("H2");
    DataSource source = mock(DataSource.class);
    when(source.getConnection()).thenReturn(connection);
    List<String> ran = new ArrayList<>();

    new MigrationsManager(config(Optional.empty()), source, seeds(seed(ran))).onInit(null);

    assertTrue(db.executed.contains("CREATE TABLE sample (id INT)"));
    assertEquals(List.of("seed"), ran);
  }

  @Test
  @DisplayName("Should build a dedicated pool when a migration JDBC url is configured")
  void shouldUseDedicatedPool() throws SQLException {
    FakeDb db = new FakeDb();
    JdbcConfig jdbc = mock(JdbcConfig.class);
    when(jdbc.url()).thenReturn(Optional.of("jdbc:mariadb://db:3306/app"));
    when(jdbc.maxSize()).thenReturn(Optional.of(2));
    when(jdbc.minSize()).thenReturn(Optional.empty());
    Connection connection = db.connection("MariaDB Connector/J");
    AgroalDataSource pool = mock(AgroalDataSource.class);
    when(pool.getConnection()).thenReturn(connection);

    try (MockedStatic<AgroalDataSource> agroal = mockStatic(AgroalDataSource.class)) {
      ArgumentCaptor<AgroalDataSourceConfiguration> configuration =
          ArgumentCaptor.forClass(AgroalDataSourceConfiguration.class);
      agroal.when(() -> AgroalDataSource.from(configuration.capture())).thenReturn(pool);

      new MigrationsManager(config(Optional.of(jdbc)), mock(DataSource.class), seeds())
          .onInit(null);

      var pooling = configuration.getValue().connectionPoolConfiguration();
      assertEquals(2, pooling.maxSize());
      assertEquals(1, pooling.minSize());
      assertEquals("jdbc:mariadb://db:3306/app",
          pooling.connectionFactoryConfiguration().jdbcUrl());
    }
    assertTrue(db.executed.contains("CREATE TABLE sample (id INT)"));
  }

  @Test
  @DisplayName("Should report a pool that cannot be built")
  void shouldReportPoolErrors() {
    JdbcConfig jdbc = mock(JdbcConfig.class);
    when(jdbc.url()).thenReturn(Optional.of("jdbc:mariadb://db:3306/app"));
    when(jdbc.maxSize()).thenReturn(Optional.empty());
    when(jdbc.minSize()).thenReturn(Optional.empty());

    try (MockedStatic<AgroalDataSource> agroal = mockStatic(AgroalDataSource.class)) {
      agroal.when(() -> AgroalDataSource.from(any(AgroalDataSourceConfiguration.class)))
          .thenThrow(new SQLException("no driver"));

      MigrationsManager manager =
          new MigrationsManager(config(Optional.of(jdbc)), mock(DataSource.class), seeds());
      assertThrows(UncheckedSqlException.class, () -> manager.onInit(null));
    }
  }

  @Test
  @DisplayName("Should report a datasource that cannot connect")
  void shouldReportConnectionErrors() throws SQLException {
    DataSource source = mock(DataSource.class);
    when(source.getConnection()).thenThrow(new SQLException("down"));
    MigrationsManager manager = new MigrationsManager(config(Optional.empty()), source, seeds());

    assertThrows(UncheckedSqlException.class, () -> manager.onInit(null));
  }
}
